  details: string;
  createdAt: Date;
  updatedAt: Date;
}

export class TicketSorter {
  private tickets: Ticket[];
  private order: SortOrder[];

  constructor(tickets: Ticket[]) {
    this.tickets = tickets;
    this.order = tickets.sort((a, b) => {
      if (a.priority === b.priority) {
        return 0;
      } else if (a.priority === "Namenort") {
        return 1;
      } else {
        return -1;
      }
    });
  }

  get sortedTickets(): Ticket[] {
    return this.tickets.slice();
  }

  get sortedTicketsWithOrder(): Ticket[] {
