```typescript
function ticketSorter(ticket: Ticket): Ticket {
  const priorities = [
    { name: 'High', priority: 100 },
    { name: 'Normal', priority: 90 },
    { name: 'Low', priority: 80 },
    { name: 'Very Low', priority: 70 },
    { name: 'Very High', priority: 60 },
    { name: 'Very Very Low', priority: 50 }
  ];

  const sortedTickets = priorities.sort((a, b) => a.priority - b.priority);

  return {
    ...ticket,
    tickets: sortedTickets.map(ticket => {
      return {
        ...ticket,
        ticketName: `${ticket.name} (Priority: ${ticket.priority})`,
        priority: ticket.priority
      };
    })
  };
}

