       private tickets: Ticket[] = [];

       // Führe die Sortierung durch
       sortTicketsByPriority() {
           this.tickets.sort((a, b) => a.priority - b.priority);
       }

       // Erwartet eine array von Tickets
       getTicketsByPriority(order: number) {
           return this.tickets.slice(0, order);
       }
   }
