       constructor(private readonly ticketController: TicketController) {
           this.ticketService = new TicketService();
       }

       getTickets() {
           return this.ticketController.getTickets();
       }

       async createTicket(ticket: Ticket): Promise<void> {
           this.ticketService.ticketCount++;
           const response = await fetch('http://example.com/tickets', {
               method: 'POST',
               body: JSON.stringify(ticket),
               headers: { 'Content-Type': 'application/json' },
